def transform(grid):
    n = len(grid) // 3
    out = [[0] * n for _ in range(n)]
    for tr in range(n):
        for tc in range(n):
            counts = {}
            for r in range(3 * tr, 3 * tr + 3):
                for c in range(3 * tc, 3 * tc + 3):
                    v = grid[r][c]
                    if v not in (0, 5):
                        counts[v] = counts.get(v, 0) + 1
            if counts:
                out[tr][tc] = max(counts, key=counts.get)
    return out
